  const visible = (objectId: string) => Boolean(state.access[objectId]?.capabilities.view && !unavailableObject(objectId));
  const boardsAvailable = visible(id) && (!sourceProxyId.current || visible(sourceProxyId.current)) && Boolean(destinationId && visible(destinationId));
  const tasksEditable = !intent || intent.input.tasks.every(task => visible(task.taskId) && state.access[task.taskId]?.capabilities.edit);
