  const chooseProject = (value: string) => { if (!replaceAllowed()) return; resetIntent(); setDestinationId(value); setDestinationColumnId(''); setDestinationBoard(value === id ? detail : null); };
  const chooseColumn = (value: string) => { if (!replaceAllowed()) return; resetIntent(); setDestinationColumnId(value); };
